let s;
let pallete = ["#10111C", "#23AECC", "#ECE1B4", "#CC3016", "#F2C96E", "#178FA6"];
let graphics;
let prevC = -1;
let ratio = 0.95;
function setup() {
  createCanvas(800, 800);
  colorMode(HSB, 360, 100, 100, 100);
  angleMode(DEGREES);

  let bgNum = int(random(pallete.length));
  let bg = pallete[bgNum];
  pallete.splice(bgNum,1);
  background(bg);

  graphics = createGraphics(width, height);
  graphics.colorMode(HSB, 360, 100, 100, 100);
  drawNoiseBackground(100000, graphics);

  s = int(random(3, 10)) * 30;

  push();
  translate(width / 2, height / 2);
  rotate(int(random(8)) * 360/8);
  for (let i = -width / 2; i < width / 2; i += (Math.max(0.001, Math.abs(s)) || 1)) {
    for (let j = -height / 2; j < height / 2; j += (Math.max(0.001, Math.abs(s)) || 1)) {
      let p1 = createVector(0 - j + 2 * i, 0 + sqrt(3) * j);
      let p2 = createVector(s - j + 2 * i, s * sqrt(3) + sqrt(3) * j);
      let p3 = createVector(-s - j + 2 * i, s * sqrt(3) + sqrt(3) * j);
      let points = [p1, p2, p3];
      let center = getCircumcenter(points);
      let r = 1* center.r;
      push();
      translate(center.x,center.y);
      rotate(30);
      let rMax = r*ratio;
      recursiveTriangles([], 0, int(random(2, 5)), rMax);      
      pop();
    }
  }
  for (let m = -width / 2; m < width / 2; m += (Math.max(0.001, Math.abs(s)) || 1)) {
    for (let n = -height / 2; n < height / 2; n += (Math.max(0.001, Math.abs(s)) || 1)) {
      let p4 = createVector(0 - m + 2 * n, 0 + sqrt(3) * m);
      let p5 = createVector(2 * s - m + 2 * n, 0 + sqrt(3) * m);
      let p6 = createVector(s - m + 2 * n, s * sqrt(3) + sqrt(3) * m);
      let points = [p4, p5, p6];
      let center = getCircumcenter(points);
      let r = 1* center.r;
      push();
      translate(center.x,center.y);
      rotate(30+180);
      let rMax = r*ratio;
      recursiveTriangles([], 0, int(random(2, 5)), rMax);      
      pop();
    }
  }
  pop();
  image(graphics, 0, 0);
  noLoop();
}

function drawConcentricTriangle(points) {
  let center = getCircumcenter(points);
  let cp = createVector(center.x, center.y);
  let step = int(random(2, 10));
  for (let a = 1; a >= 0; a -= 1 / step) {
    let c = prevC;
    let _wG_1 = 0; while ((c == prevC) && ++_wG_1 < 20000) {
      c = random(pallete);
    }
    prevC = c;
    noStroke();
    fill(c);
    beginShape();
    for (let p of points) {
      let x = lerp(cp.x, p.x, a);
      let y = lerp(cp.y, p.y, a);
      vertex(x, y);
    }
    endShape(CLOSE);
  }

}


function getCircumcenter(points) {
  let a = points[0].x;
  let b = points[0].y;
  let c = points[1].x;
  let d = points[1].y;
  let e = points[2].x;
  let f = points[2].y;

  let aa = a * a;
  let bb = b * b;
  let cc = c * c;
  let dd = d * d;
  let ee = e * e;
  let ff = f * f;

  let py = ((e - a) * (aa + bb - cc - dd) - (c - a) * (aa + bb - ee - ff)) / (2 * (e - a) * (b - d) - 2 * (c - a) * (b - f))

  let px = ((c - a) == 0) ? (2 * (b - d) * py - aa - bb + cc + dd) / (2 * (c - a)) : (2 * (b - f) * py - aa - bb + ee + ff) / (2 * (e - a));

  pr = sqrt(sq(px - a) + sq(py - b));
  return {
    x: int(px),
    y: int(py),
    r: int(pr)
  };
}

function drawNoiseBackground(_n, _graphics) {
  let c = color(0, 0, 100, 5);
  for (let i = 0; i < _n; i++) {
    let x = random(1) * width;
    let y = random(1) * height;
    let w = random(1, 2);
    let h = random(1, 2);
    _graphics.noStroke();
    _graphics.fill(c);
    _graphics.ellipse(x, y, w, h);
  }
}

function recursiveTriangles(arr, depth, max, rMax = width / 2) {
  noStroke();
  if (depth > max) {
    let p1 = arr[0];
    let p2 = arr[1];
    let p3 = arr[2];
    let p4 = p5.Vector.lerp(p1,p2,0.5);
    let centroid = p5.Vector.lerp(p3,p4,2/3);
    let num = int(random(2,5))*10;
    let c1 = color(random(pallete));
    let c2 = c1;
    let _wG_2 = 0; while ((c1 == c2) && ++_wG_2 < 20000){
      c2 = color(random(pallete));
    }
    for(let i = 1; i >0; i -= 1/num){
      colorMode(RGB,255,255,255,255);
      fill(lerpColor(c1,c2,i));
      beginShape();
      for(let pp of arr){
        let p = p5.Vector.lerp(centroid,pp,i);
        vertex(p.x,p.y);
      }
      endShape(CLOSE);
      colorMode(HSB,360,100,100,100);
    }
    return;
  }
  if (depth == 0) {
    let r = rMax;
    let startAngle = 0;//int(random(12)) * 360/12;
    for (let angle = startAngle; angle < 360 + startAngle; angle += (Math.max(0.001, Math.abs(360 / 3)) || 1)) {
      let x = cos(angle) * r;
      let y = sin(angle) * r;
      arr.push(createVector(x, y));
    }
    noStroke();
  }
  let target = int(random(arr.length));
  let next = (target + 1) % arr.length;
  let current = p5.Vector.lerp(arr[target], arr[next], 0.5);
  triangle(arr[target].x, arr[target].y, arr[(next + 1) % arr.length].x, arr[(next + 1) % arr.length].y, current.x, current.y);
  recursiveTriangles([arr[target], arr[(next + 1) % arr.length], current], depth + 1, max);
  triangle(arr[next].x, arr[next].y, arr[(next + 1) % arr.length].x, arr[(next + 1) % arr.length].y, current.x, current.y);
  recursiveTriangles([arr[next], arr[(next + 1) % arr.length], current], depth + 1, max);
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
